const data = $json;

const risks = (data.key_risks || [])
  .map(risk => `<li>${risk}</li>`)
  .join('');

const conditions = (data.conditions || [])
  .map(condition => `<li>${condition}</li>`)
  .join('');

const reviews = (data.human_review_required || [])
  .map(item => `<li>${item}</li>`)
  .join('');

const recommendation = String(data.recommendation || '');

let statusClass = 'ready';

if (recommendation === 'Conditional') {
  statusClass = 'conditional';
} else if (recommendation === 'Not Ready') {
  statusClass = 'not-ready';
}

const report = `
