  {
    json: {
      html_report: report,
      email_subject: `Release ${data.product} v${data.version} — ${data.recommendation}`
    }
  }
];

const markdown = $input.first().json.data;

if (!markdown || typeof markdown !== 'string') {
  throw new Error('GitHub markdown data is missing or invalid.');
}

const lines = markdown
  .split('\n')
  .map(line => line.trim());

// =====================================================
// Helper Functions
// =====================================================

function getValue(label) {
  const line = lines.find(line =>
    line.startsWith(`* **${label}:**`)
  );

  if (!line) return '';

  return line
    .replace(`* **${label}:**`, '')
    .trim();
}

function parseTableRow(line) {
  return line
    .split('|')
    .map(value => value.trim())
    .filter(Boolean);
}

function findSectionStart(sectionName) {
  return lines.findIndex(line =>
    line.includes(sectionName)
  );
}

function findSectionEnd(startIndex) {
  if (startIndex === -1) {
    return lines.length;
  }

  const end = lines.findIndex((line, index) =>
    index > startIndex &&
    line === '---'
  );

  return end === -1 ? lines.length : end;
}

// =====================================================
// 1. RELEASE INFORMATION
// =====================================================

const release = {
  product: getValue('Product'),
  version: getValue('Release Version'),
  planned_release_date: getValue('Planned Release Date'),
  release_type: getValue('Release Type'),
  release_owner: getValue('Release Owner'),
  qa_owner: getValue('QA Owner'),
  deployment_owner: getValue('Deployment Owner'),
  target_environment: getValue('Target Environment'),
  previous_version: getValue('Previous Version'),
  release_status: getValue('Release Status'),
  main_goal: getValue('Main Goal')
};

// =====================================================
// 2. CHANGES
// =====================================================

const changes = [];

const changeSectionStart = findSectionStart(
  '# Resource 2: Changes'
);

const changeStart = lines.findIndex((line, index) =>
  index > changeSectionStart &&
  line.startsWith('| CH')
);

const changeEnd = findSectionEnd(changeSectionStart);

if (changeStart !== -1) {

  for (let i = changeStart; i < changeEnd; i++) {

    const line = lines[i];

    if (!line.startsWith('| CH')) continue;

    const parts = parseTableRow(line);

    if (parts.length < 6) continue;

    changes.push({
      id: parts[0],
      type: parts[1],
      area: parts[2],
      change: parts[3],
      status: parts[4],
      description: parts[5]
    });
  }
}

// =====================================================
// 3. QA TESTS
// =====================================================

const qa_tests = [];

const qaSectionStart = findSectionStart(
  '# Resource 3: QA'
);

const qaStart = lines.findIndex((line, index) =>
  index > qaSectionStart &&
  line.startsWith('| T')
);

const qaEnd = findSectionEnd(qaSectionStart);

if (qaStart !== -1) {

  for (let i = qaStart; i < qaEnd; i++) {

    const line = lines[i];

    if (!line.startsWith('| T')) continue;

    const parts = parseTableRow(line);

    if (parts.length < 6) continue;

    qa_tests.push({
      id: parts[0],
      area: parts[1],
      test_case: parts[2],
      result: parts[3],
      priority: parts[4],
      notes: parts[5]
    });
  }
}

// =====================================================
// 4. DEFECTS
// =====================================================

const defects = [];

const defectSectionStart = findSectionStart(
  '# Resource 4: Defects'
);

const defectStart = lines.findIndex((line, index) =>
  index > defectSectionStart &&
  line.startsWith('| BUG')
);

const defectEnd = findSectionEnd(defectSectionStart);

if (defectStart !== -1) {

  for (let i = defectStart; i < defectEnd; i++) {

    const line = lines[i];

    if (!line.startsWith('| BUG')) continue;

    const parts = parseTableRow(line);

    if (parts.length < 7) continue;

    defects.push({
      id: parts[0],
      area: parts[1],
      severity: parts[2],
      description: parts[3],
      business_impact: parts[4],
      workaround: parts[5],
      status: parts[6]
    });
  }
}

// =====================================================
// 5. WORKAROUNDS
// =====================================================

const workarounds = [];

const workaroundSectionStart = findSectionStart(
  '# Resource 4.1: Workarounds'
);

const workaroundEnd = findSectionEnd(
  workaroundSectionStart
);

if (workaroundSectionStart !== -1) {

  for (
    let i = workaroundSectionStart;
    i < workaroundEnd;
    i++
  ) {

    const line = lines[i];

    if (!line.startsWith('| BUG')) continue;

    const parts = parseTableRow(line);

    if (parts.length < 2) continue;

    workarounds.push({
      defect_id: parts[0],
      workaround: parts[1]
    });
  }
}

// =====================================================
// 6. RELEASE RULES
// =====================================================

const rules = {

  ready: [
    'No major issue prevents release.',
    'Remaining risks are acceptable.',
    'Required reviews and approvals are completed.'
  ],

  conditional: [
    'The release may proceed only after specific actions.',
    'Required approvals are completed.',
    'Required risk acceptance is confirmed.'
  ],

  not_ready: [
    'Important issues must be resolved before release.'
  ],

  critical_defect: [
    'Release should not proceed until the defect is resolved.'
  ],

  high_defect: [
    'Normally should not proceed.',
    'Requires formal approval and a strong business reason if an exception is considered.'
  ],

  medium_defect: [
    'Business impact is understood.',
    'A workaround exists where needed.',
    'Risk acceptance is confirmed.'
  ],

  low_defect: [
    'May normally proceed if the issue is documented and assessed as acceptable.'
  ],

  critical_test_failure: [
    'Release should be Not Ready.'
  ],

  high_priority_test_failure: [
    'Investigation is required before approval.'
  ],

  medium_priority_test_failure: [
    'Assess business impact and workaround.'
  ],

  low_priority_test_failure: [
    'Document the failure and assess acceptability.'
  ],

  regression_failure: [
    'Requires careful review.'
  ],

  security_failure: [
    'Release should not proceed until the failure is reviewed/resolved.'
  ],

  general: [
    'AI can assess the release but cannot approve production.',
    'The Technical Lead makes the final production decision.',
    'Any unresolved Critical or High defect must be clearly highlighted.',
    'Medium defects must include business impact and workaround information.',
    'Accepted known issues must be included in the final report.',
    'Failed tests must not be hidden or minimized just because most tests passed.',
    'Incomplete, conflicting, or uncertain information must be identified and sent for human review.',
    'A workaround does not automatically mean that a risk has been accepted.',
    'Risk acceptance must only be considered confirmed when the input explicitly states that it is confirmed.',
    'If required risk acceptance is not confirmed, it must be identified as pending human review.'
  ]

};

// =====================================================
// FINAL OUTPUT
// =====================================================

return [
  {
    json: {
      release,
      changes,
      qa_tests,
      defects,
      workarounds,
      rules
    }
  }
];

const raw = $json.output;

try {
  const result = JSON.parse(raw);

  return [
    {
      json: result
