let raw = $json.output;

if (!raw || raw.trim() === "") {
  throw new Error("Release Policy Agent returned an empty response");
}

// Strip markdown code fences if present (```json ... ``` or ``` ... ```)
raw = raw.trim();
raw = raw.replace(/^```(?:json)?\s*/i, "");
raw = raw.replace(/```\s*$/i, "");
raw = raw.trim();

let parsed;
try {
  parsed = JSON.parse(raw);
} catch (error) {
  throw new Error("Invalid JSON from Release Policy Agent: " + raw);
}

return [{ json: parsed }];

const raw = $json.output;

if (!raw || raw.trim() === "") {
  throw new Error("Final Assessment Agent returned an empty response");
}

let result;

try {
  result = JSON.parse(raw);
} catch (error) {
  throw new Error("Invalid JSON from Final Assessment Agent: " + raw);
}

// Get QA data from the actual output of QA Evidence Agent
const qaRaw = $('QA Evidence Agent').first().json.output;

if (!qaRaw || qaRaw.trim() === "") {
  throw new Error("QA Evidence Agent returned empty output");
}

let qa;

try {
  qa = JSON.parse(qaRaw);
} catch (error) {
  throw new Error("Invalid JSON from QA Evidence Agent: " + qaRaw);
}

// const total = qa.total_tests;
// const passed = qa.passed_tests;
// const failed = qa.failed_tests;

return [{
  json: {
    ...result,

    human_review_required: result.human_review_required || []
  }
}];

const data = $json;

// Safely escape HTML
const escapeHtml = (value) => {
  return String(value ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
};

const conditions = (data.conditions || [])
  .map(item => `<li>${escapeHtml(item)}</li>`)
  .join('');

const reviews = (data.human_review_required || [])
  .map(item => `<li>${escapeHtml(item)}</li>`)
  .join('');

const risks = (data.key_risks || [])
  .map(item => `<li>${escapeHtml(item)}</li>`)
  .join('');

const recommendation = escapeHtml(data.recommendation || 'Conditional');
const product = escapeHtml(data.product || '-');
const version = escapeHtml(data.version || '-');
const releaseGoal = escapeHtml(data.release_goal || 'No release goal provided.');
const changeSummary = escapeHtml(data.change_summary || 'No change summary provided.');
